import React, { useState } from 'react';

function ReportCenter() {
  const [activeReport, setActiveReport] = useState('hr');

  const reports = [
    { key: 'hr', icon: '👥', title: 'Báo Cáo Nhân Sự', desc: 'Tổng hợp biến động nhân sự', role: 'HR Manager' },
    { key: 'payroll', icon: '💰', title: 'Báo Cáo Chi Phí Lương', desc: 'Phân tích chi phí lương', role: 'Payroll Manager' },
    { key: 'attendance', icon: '📅', title: 'Báo Cáo Chấm Công', desc: 'Thống kê ngày công', role: 'Admin' },
    { key: 'dept', icon: '🏢', title: 'Báo Cáo Phòng Ban', desc: 'Cơ cấu nhân sự', role: 'Admin' },
  ];

  return (
    <div className="animate-fade-in">
      <div className="row g-3 mb-4">
        {reports.map(r => (
          <div className="col-md-6 col-xl-3" key={r.key}>
            <div className="stat-card" style={{cursor: 'pointer',
              border: activeReport === r.key ? '2px solid var(--primary)' : '1px solid var(--border-color)'
            }} onClick={() => setActiveReport(r.key)}>
              <div style={{fontSize: 32, marginBottom: 8}}>{r.icon}</div>
              <h6 style={{fontWeight: 700, fontSize: 14}}>{r.title}</h6>
              <p className="text-muted mb-1" style={{fontSize: 12}}>{r.desc}</p>
              <span className="badge-status" style={{background: 'rgba(79,70,229,0.1)', color: '#4f46e5', fontSize: 10}}>{r.role}</span>
            </div>
          </div>
        ))}
      </div>

      <div className="content-card">
        <div className="card-header-custom">
          <h5>📈 {reports.find(r => r.key === activeReport)?.title}</h5>
          <div className="d-flex gap-2">
            <select className="form-select form-select-sm" style={{width: 150}}>
              <option>Tháng 5/2026</option><option>Tháng 4/2026</option><option>Tháng 3/2026</option>
            </select>
            <button className="btn btn-primary-custom btn-sm">📥 Xuất Excel</button>
          </div>
        </div>
        <div className="p-4">
          <p className="text-center text-muted py-4">Chưa có dữ liệu báo cáo. Kết nối Backend để xem.</p>
        </div>
      </div>
    </div>
  );
}

export default ReportCenter;
